static const uint8_t z_empty[] = {
    0x78, 0xda, 0x03, 0x00, 0x00, 0x00, 0x00, 0x01,
};

#define DATA_LEN 5000
static uint8_t expect[DATA_LEN], out[DATA_LEN + 64], bad[1226];

static void ok(const uint8_t *z, size_t n, size_t want)
{
    size_t got = 0;
    memset(out, 0xAA, sizeof out);
    CHECK_EQ(zlib_inflate(z, n, out, sizeof out, &got), INFLATE_OK);
    CHECK_EQ(got, want);
    CHECK(memcmp(out, expect, want) == 0);
}

TEST(decodes_all_block_types)
{
    CHECK_EQ(gen(expect, DATA_LEN), (size_t)DATA_LEN);
    ok(z_stored, sizeof z_stored, DATA_LEN);
    ok(z_fixed, sizeof z_fixed, DATA_LEN);
    ok(z_dynamic, sizeof z_dynamic, DATA_LEN);
    size_t got = 1;
    CHECK_EQ(zlib_inflate(z_empty, sizeof z_empty, out, sizeof out, &got), INFLATE_OK);
    CHECK_EQ(got, (size_t)0);
}

TEST(refuses_bad_input)
{
    size_t got;
    /* output buffer one byte too small */
    CHECK_EQ(zlib_inflate(z_dynamic, sizeof z_dynamic, out, DATA_LEN - 1, &got), INFLATE_EFULL);
    CHECK_EQ(zlib_inflate(z_stored, sizeof z_stored, out, DATA_LEN - 1, &got), INFLATE_EFULL);
    /* truncated */
    CHECK(zlib_inflate(z_dynamic, sizeof z_dynamic / 2, out, sizeof out, &got) < 0);
    CHECK(zlib_inflate(z_dynamic, 5, out, sizeof out, &got) < 0);
    /* wrong header */
    memcpy(bad, z_dynamic, sizeof bad);
    bad[0] = 0x79;
    CHECK_EQ(zlib_inflate(bad, sizeof bad, out, sizeof out, &got), INFLATE_EHEADER);
    /* checksum */
    memcpy(bad, z_dynamic, sizeof bad);
    bad[sizeof bad - 1] ^= 1;
    CHECK_EQ(zlib_inflate(bad, sizeof bad, out, sizeof out, &got), INFLATE_ECHECK);
    /* every single-byte corruption of the body is either refused or caught
     * by the checksum, and never writes past the buffer */
    int caught = 0;
    for (size_t i = 2; i + 4 < sizeof bad; i += 7) {
        memcpy(bad, z_dynamic, sizeof bad);
        bad[i] ^= 0x5A;
        int r = zlib_inflate(bad, sizeof bad, out, DATA_LEN, &got);
        caught += r != INFLATE_OK;
        CHECK(got <= DATA_LEN);
    }
    CHECK(caught > 0);
    CHECK_EQ(adler32((const uint8_t *)"Wikipedia", 9), 0x11E60398u);
}

void run_tests(void)
{
    RUN(decodes_all_block_types);
    RUN(refuses_bad_input);
}
